// 锁同时提供互斥与可见性
class Counter {
    private int count;
    private final Object lock = new Object();   // 专用锁对象

    void inc() {
        synchronized (lock) {   // monitorenter：清空副本，重新读主内存
            count++;            // 读-改-写，整段互斥
        }                       // monitorexit：把修改刷回主内存
    }

    int get() {
        synchronized (lock) {   // 不加锁的读可能看到旧值
            return count;
        }
    }
}

