// 错误版本：看起来没问题，实际上可能返回半初始化对象
class BadSingleton {
    private static BadSingleton instance;      // 少了 volatile

    private BadSingleton() { /* 假设这里有很多字段初始化 */ }

    static BadSingleton getInstance() {
        if (instance == null) {                // 第一次检查，无锁
            synchronized (BadSingleton.class) {
                if (instance == null) {        // 第二次检查，有锁
                    instance = new BadSingleton();  // 三步可能被重排
                }
            }
        }
        return instance;
    }
}

// 修复一：volatile 版 DCL
class Singleton {
    private static volatile Singleton instance;   // 关键的一处改动
    private Singleton() { }
    static Singleton getInstance() {
        if (instance == null) {
            synchronized (Singleton.class) {
                if (instance == null) instance = new Singleton();
            }
        }
        return instance;
    }
}

