// this 逃逸的四种典型写法
class Leaky {
    private int value;

    Leaky(EventBus bus) {
        bus.register(this);          // ① 构造期注册监听器
        new Thread(this::work).start(); // ② 构造期启动线程
        Global.CACHE.put("k", this);    // ③ 构造期存入全局容器
        init();                      // ④ 调用可被重写的方法
        value = 42;
    }
    void init() { }                  // 子类可能重写，在 value 赋值前执行
    void work() { System.out.println(value); }
}

